import java.util.Objects;

/**
 * Represents the {@code geometry} data type, which models planar (cartesian) spatial data. A {@code
 * GeometryType} carries a Spatial Reference System Identifier (SRID) using the {@code
 * authority:code} notation (e.g. {@code OGC:CRS84}, {@code EPSG:4326}).
 *
 * <p>Two {@code GeometryType} instances are equal if and only if they have the same SRID. SRID
 * matching is case-sensitive.
 *
 * @since 4.0.0
 */
@Evolving
public final class GeometryType extends DataType {

  /** Default SRID used when none is explicitly provided. */
  private static final String DEFAULT_SRID = "OGC:CRS84";

  private final String srid;

  private GeometryType(String srid) {
    this.srid = srid;
  }

  /** Returns a {@link GeometryType} using the default SRID {@code OGC:CRS84}. */
  public static GeometryType ofDefault() {
    return new GeometryType(DEFAULT_SRID);
  }

  /** Returns a {@link GeometryType} using the given SRID. */
  public static GeometryType ofSRID(String srid) {
    return new GeometryType(srid);
  }

  /** Returns the Spatial Reference System Identifier (SRID) of this type. */
  public String getSrid() {
    return srid;
  }

  @Override
  public boolean isNested() {
    return false;
  }

  @Override
  public String toString() {
    return String.format("Geometry(srid=%s)", srid);
  }

  @Override
  public boolean equals(Object o) {
    if (this == o) {
      return true;
    }
    if (o == null || getClass() != o.getClass()) {
      return false;
    }
    GeometryType that = (GeometryType) o;
    return Objects.equals(srid, that.srid);
  }

  @Override
  public int hashCode() {
    return Objects.hash(srid);
  }
}
