package io.delta.kernel.types;

import io.delta.kernel.annotation.Evolving;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;

/**
 * Represents the {@code geography} data type, which models geodetic (spherical) spatial data. A
 * {@code GeographyType} carries a Spatial Reference System Identifier (SRID) using the {@code
 * authority:code} notation (e.g. {@code OGC:CRS84}, {@code EPSG:4326}) and a geodetic calculation
 * algorithm.
 *
 * <p>Valid algorithms are: {@code spherical}, {@code vincenty}, {@code thomas}, {@code andoyer},
 * {@code karney}.
 *
 * <p>Two {@code GeographyType} instances are equal if and only if they have the same SRID and
 * algorithm. SRID matching is case-sensitive.
 *
 * @since 4.0.0
 */
@Evolving
public final class GeographyType extends DataType {

  /** Default SRID used when none is explicitly provided. */
  private static final String DEFAULT_SRID = "OGC:CRS84";

  /** Default geodetic calculation algorithm used when none is explicitly provided. */
  private static final String DEFAULT_ALGORITHM = "spherical";

  /** The set of supported geodetic calculation algorithms. */
  private static final List<String> VALID_ALGORITHMS =
      Arrays.asList("spherical", "vincenty", "thomas", "andoyer", "karney");

  private final String srid;
  private final String algorithm;

  /**
   * Constructs a {@link GeographyType} with the given SRID and algorithm.
   *
   * @throws IllegalArgumentException if {@code algorithm} is not one of the supported algorithms.
   */
  public GeographyType(String srid, String algorithm) {
    if (!VALID_ALGORITHMS.contains(algorithm)) {
      throw new IllegalArgumentException(
          "Algorithm must be one of: spherical, vincenty, thomas, andoyer, karney");
    }
    this.srid = srid;
    this.algorithm = algorithm;
  }

  /** Returns a {@link GeographyType} using the default SRID {@code OGC:CRS84} and algorithm. */
  public static GeographyType ofDefault() {
    return new GeographyType(DEFAULT_SRID, DEFAULT_ALGORITHM);
  }

  /** Returns a {@link GeographyType} using the given SRID and the default algorithm. */
  public static GeographyType ofSRID(String srid) {
    return new GeographyType(srid, DEFAULT_ALGORITHM);
  }

  /** Returns a {@link GeographyType} using the default SRID and the given algorithm. */
  public static GeographyType ofAlgorithm(String algorithm) {
    return new GeographyType(DEFAULT_SRID, algorithm);
  }

  /** Returns the Spatial Reference System Identifier (SRID) of this type. */
  public String getSrid() {
    return srid;
  }

  /** Returns the geodetic calculation algorithm of this type. */
  public String getAlgorithm() {
    return algorithm;
  }

  @Override
  public boolean isNested() {
    return false;
  }

  @Override
  public String toString() {
    return String.format("Geography(srid=%s, algorithm=%s)", srid, algorithm);
  }

  @Override
  public boolean equals(Object o) {
    if (this == o) {
      return true;
    }
    if (o == null || getClass() != o.getClass()) {
      return false;
    }
    GeographyType that = (GeographyType) o;
    return Objects.equals(srid, that.srid) && Objects.equals(algorithm, that.algorithm);
  }

  @Override
  public int hashCode() {
    return Objects.hash(srid, algorithm);
  }
}
